keyframes:
@keyframes ui-as-guide-out { 
  100% { opacity: 0; }
}

@keyframes ui-as-guide-in { 
  0% { opacity: 0; transform: translateY(6px); }
  100% { opacity: 1; transform: none; }
}

@keyframes ui-as-popover-up { 
  0% { opacity: 0; transform: scale(0.96) translateY(4px); }
  100% { opacity: 1; transform: none; }
}

@keyframes ui-as-rise { 
  0% { opacity: 0; transform: translateY(8px); }
  100% { opacity: 1; transform: none; }
}

@keyframes ui-as-pop { 
  0% { opacity: 0; transform: scale(0.6); }
  100% { opacity: 1; transform: none; }
}

@keyframes ui-as-popover { 
  0% { opacity: 0; transform: scale(0.96) translateY(-4px); }
  100% { opacity: 1; transform: none; }
}

@keyframes ui-as-toast { 
  0% { opacity: 0; transform: translateY(12px) scale(0.96); }
  12%, 85% { opacity: 1; transform: none; }
  100% { opacity: 0; transform: translateY(6px); }
}

@keyframes ui-ar-breathe { 
  50% { opacity: 0.35; }
}

@keyframes ui-ar-panel-in { 
  0% { transform: translateX(40px); opacity: 0; }
  100% { transform: none; opacity: 1; }
}

@keyframes ui-ar-fade { 
  0% { opacity: 0; }
}

@keyframes ui-button-label-in { 
  0% { opacity: 0; filter: blur(3px); transform: translateY(25%); }
}

@keyframes ui-button-icon-in { 
  0% { opacity: 0; filter: blur(2px); transform: scale(0.7); }
}

@keyframes ui-button-spin { 
  100% { transform: rotate(1turn); }
}

@keyframes ui-button-sweep { 
  0% { background-position: 100% 0px; }
  100% { background-position: 0% 0px; }
}

@keyframes ui-pl-fade { 
  0% { opacity: 0; transform: translateY(3px); }
  100% { opacity: 1; transform: none; }
}

@keyframes ui-pl-enter { 
  0% { opacity: 0; transform: translateY(6px); }
  100% { opacity: 1; transform: none; }
}

@keyframes ui-pl-pop { 
  0% { opacity: 0; transform: scale(0.5); }
  100% { opacity: 1; transform: none; }
}

@keyframes ui-pl-draw { 
  100% { stroke-dashoffset: 0; }
}

@keyframes ui-pl-ray { 
  0% { opacity: 1; }
  100% { opacity: 0.18; }
}

@keyframes ui-tl-ray { 
  0% { opacity: 1; }
  100% { opacity: 0.18; }
}

@keyframes ui-tl-in { 
  0% { opacity: 0; transform: translateY(70%); filter: blur(3px); }
  100% { opacity: 1; transform: none; filter: none; }
}

@keyframes ui-tl-out { 
  0% { opacity: 1; transform: none; filter: none; }
  100% { opacity: 0; transform: translateY(-70%); filter: blur(3px); }
}

@keyframes ui-tl-draw { 
  100% { stroke-dashoffset: 0; }
}

@keyframes ui-tl-sweep { 
  0% { background-position: 100% 0px; }
  100% { background-position: 0% 0px; }
}

@keyframes ui-df-draw { 
  100% { stroke-dashoffset: 0; }
}

@keyframes ui-chat-composer-sweep { 
  0% { background-position: 100% 0px; }
  100% { background-position: 0% 0px; }
}

@keyframes ui-chat-composer-hop { 
  0%, 70%, 100% { transform: translateY(0px); }
  32% { transform: translateY(calc(-13 * var(--u))); }
}

@keyframes ui-chat-composer-wave { 
  0%, 76%, 100% { transform: rotate(0deg); }
  18% { transform: rotate(16deg); }
  38% { transform: rotate(-10deg); }
  58% { transform: rotate(7deg); }
}

@keyframes ui-chat-composer-model-in { 
  0% { opacity: 0; filter: blur(3px); transform: translateY(30%); }
}

@keyframes ui-chat-composer-logo-in { 
  0% { opacity: 0; transform: scale(0.6) rotate(-12deg); }
}

@keyframes ui-tc-in { 
  0% { opacity: 0; transform: translateY(3px); filter: blur(2px); }
  100% { opacity: 1; transform: none; filter: none; }
}

@keyframes ui-tc-pop { 
  0% { opacity: 0; transform: scale(0.6); }
  100% { opacity: 1; transform: none; }
}

@keyframes ui-tc-spin { 
  100% { transform: rotate(360deg); }
}

@keyframes ui-tc-draw { 
  100% { stroke-dashoffset: 0; }
}

@keyframes ui-tc-sweep { 
  0% { background-position: 100% 0px; }
  100% { background-position: 0% 0px; }
}

@keyframes lp-pop { 
  0% { opacity: 0; transform: translateY(-4px) scale(0.98); }
}

@keyframes lp-iso-in { 
  0% { opacity: 0; }
}

@keyframes lp-iso-scroll { 
  100% { transform: translateY(-33.3333%); }
}

@keyframes lp-rise { 
  0% { opacity: 0; filter: blur(4px); transform: translateY(10px); }
}

@keyframes lp-fade { 
  0% { opacity: 0; transform: translateY(6px); }
}
